changeSet.sql:
UPDATE programming_exercise_build_config
SET advanced_settings = json_build_object('branching', json_build_object('allowed', allow_branching, 'regex', branch_regex))
WHERE allow_branching = TRUE OR (branch_regex IS NOT NULL AND branch_regex <> '.*');

UPDATE programming_exercise_build_config
SET advanced_settings = JSON_OBJECT('branching', JSON_OBJECT('allowed', IF(allow_branching = TRUE, CAST('true' AS JSON), CAST('false' AS JSON)), 'regex', branch_regex))
WHERE allow_branching = TRUE OR (branch_regex IS NOT NULL AND branch_regex <> '.*');
